{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Captopril, the closest analogue sharing the same 3-mercapto-2-methylpropanoyl-proline scaffold, has an absolute oral bioavailability of 62% in healthy subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Quinapril, a structurally related ACE inhibitor, has an absolute oral bioavailability of about 46% in humans, supporting the high-bioavailability pattern for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Moexipril, the least bioavailable among the related ACE inhibitors listed, still achieves 22% oral bioavailability, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Perindopril has reported absolute oral bioavailability values of 66–95%, further supporting high oral bioavailability for ACE inhibitor analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Argatroban has poor oral bioavailability in humans, but it is structurally distant from the query and not an ACE inhibitor, so this contradictory evidence carries little transfer weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is zofenoprilat, a phenylthio-substituted captopril analogue. The closest and most transferable evidence, captopril, shows absolute oral bioavailability of 62%, well above the 20% threshold. Other ACE inhibitors, including quinapril, moexipril, and perindopril, also exceed 20%. The only low-bioavailability analogue, argatroban, is structurally dissimilar and does not outweigh the strong class-level evidence. Therefore, the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for zofenoprilat itself are provided; most evidence comes from captopril and ACE inhibitor prodrugs.",
    "Perindoprilat active-metabolite data are mixed (19–30%) and reflect systemic availability after prodrug administration rather than direct oral dosing of the diacid."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

